"""Context coverage; executed within author_research.py."""
gender=['Entry and advancement','Milestones','Networks and pathways','Role and portfolio allocation','Campaign and media treatment','Threats and security','Gender-related policy and organizations','Political use of identity','Representation and effects','Assessment over time']
era=['Party system','Constitutional and institutional environment','Electoral environment','Economic regime','International system','Media and campaign environment','Political organization','Social environment','State structure and political geography','Evidence environment']
coverage={'Gender':gender,'Era':era}

gender_rows=[
('Women’s and youth Congress roles preceded parliamentary advancement. The sources document this pathway but do not isolate gender as a cause of selection or as a barrier.',[1],'Material finding','Compare contemporary party organisers with equivalent experience; no matched promotion study was retrieved.'),
('Her 2011 accession made her West Bengal’s first woman Chief Minister. This is a milestone in holding office, distinct from changes in women’s everyday power.',[32],'Material finding','Regional milestone; not a claim that she was India’s first woman CM.'),
('Movement allies and party organisation enabled her rise. Later prominence of nephew Abhishek makes family succession relevant; personal emergence outside a ruling dynasty does not preclude later family networks.',[15,46],'Material finding','Assess the founder’s entry and the next generation’s promotion separately.'),
('Her career combined early women’s organisation work, junior HRD service, Railways, Coal and Mines, and state executive leadership. It cannot be reduced to gender-designated portfolios.',[1],'Material finding','Compare ministerial rank, appointment route and period; do not assume why a portfolio was assigned.'),
('Chaudhury examines gendered descriptions of authority, austerity and Didi imagery. The study interprets selected texts and interviews; it is not a systematic count of all media treatment.',[14],'Material finding','Situate descriptions in their political and linguistic setting rather than applying present-day labels mechanically.'),
('The Hazra assault documents political vulnerability; the collected evidence does not establish that gender caused the attack or quantify differential security constraints.',[46],'Evidence not found','Gender-specific threat mechanisms need incident records and contemporary comparators; this gap is not evidence of absence.'),
('Kanyashree targets girls’ schooling and marriage timing; Lakshmir Bhandar targets women’s income support. Gender relevance follows programme design, while effectiveness requires outcome evidence.',[17,18],'Material finding','Eligibility, actual receipt and control of benefits are separate measures.'),
('Didi kinship, Bengali cultural references and religious imagery feature in the scholarly analysis of her political persona. These are public strategies and interpretations, not assumptions about private belief.',[14],'Material finding','Avoid imputing a caste or religious motive to every policy or voter.'),
('A woman in the top state office supplies descriptive representation. Kanyashree findings and safety failures at RG Kar show why substantive equality must be assessed across distinct institutions and outcomes.',[32,17,23],'Research limitation','No evidence here isolates the leader’s sex as the causal explanation for programme adoption or safety outcomes.'),
('Early fighter imagery, later welfare leadership and criticism over sexual-violence responses coexist in the record. Legacy assessment must include each rather than infer universal empowerment from personal success.',[46,17,47,23],'Material finding','Separate retrospective biography, contemporary criticism, court findings and measured programme outcomes.'),
]
for n,(finding,ids,disposition,caution) in enumerate(gender_rows,1):
    add('Context & Constraints',f'G{n:02d}',{'Career phase':'Across phases; event-specific dates in linked records',
        'Coverage dimension':'Gender','Coverage item':gender[n-1],'Research disposition':disposition,
        'Finding':finding,'Contemporary comparison / caution':caution},ids,'Analysis',
        status='Not reviewed' if disposition=='Evidence not found' else 'Supported',
        note='Candidate source establishes political violence; gender-specific mechanism remains an open research question.' if n==6 else '')

